window.BoraAssistant={
 page(u){const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return `<div class="narrow"><div class="eyebrow">Твой помощник · объясняем по-человечески</div><h1>Давай разберёмся.</h1><p>Задай вопрос, пришли свою фразу или попроси потренировать диалог. Объяснения — на русском, примеры — на бразильском португальском.</p><div class="panel"><form id="tutor-form"><p class="pill">🇧🇷 Бразильский португальский</p><label>Твой вопрос<textarea id="tutor-question" maxlength="1500" required placeholder="Почему здесь ser, а здесь estar?">${escape(u.tutorLanguage==='en'?'':u.tutorDraft||'')}</textarea></label><button class="btn" id="tutor-send">Спросить помощника →</button><p class="small">Вопрос, несколько последних сообщений и учебная цель передаются в GigaChat. История сохраняется в твоём аккаунте.</p></form><div id="tutor-status" role="status" aria-live="polite"></div></div><div id="tutor-messages" style="margin-top:20px"></div></div>`},
 bind(u,save){const form=document.querySelector('#tutor-form');if(!form)return;const question=document.querySelector('#tutor-question'),status=document.querySelector('#tutor-status'),send=document.querySelector('#tutor-send'),messages=document.querySelector('#tutor-messages');let busy=false;
 const paint=()=>{messages.replaceChildren();for(const m of (u.chat||[]).filter(m=>m.language!=='en').slice(-12)){const card=document.createElement('article');card.className='card';card.style.marginBottom='12px';const name=document.createElement('strong');name.textContent=m.role==='user'?'Ты':'Bora';const text=document.createElement('p');text.style.whiteSpace='pre-wrap';text.style.marginTop='12px';text.textContent=m.content;card.append(name,text);for(const s of m.sources||[]){let url;try{url=new URL(s.url);if(url.protocol!=='https:'&&url.protocol!=='http:')continue}catch{continue}const a=document.createElement('a');a.href=url.href;a.target='_blank';a.rel='noopener noreferrer';a.className='small';a.textContent=`[${s.number}] ${s.title}${s.page?' · стр. '+s.page:''} · ${s.license}`;a.style.display='block';card.append(a)}messages.append(card)}};paint();
 question.oninput=()=>{u.tutorDraft=question.value;save()};
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;const q=question.value.trim();if(!q)return;busy=true;send.disabled=true;status.textContent='Ищу в библиотеке и готовлю объяснение…';const selected='pt-BR';u.tutorLanguage=selected;
 try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+await window.BoraAccount.accessToken()},body:JSON.stringify({question:q,language:selected,history:(u.chat||[]).filter(m=>m.language===selected).slice(-6).map(m=>({role:m.role,content:m.content})),learner:{goal:u.goal,experience:u.experience,diagnosis:u.diagnosis?.summary||''}}),signal:AbortSignal.timeout(120000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Не удалось получить ответ');u.chat=[...(u.chat||[]),{role:'user',content:q,language:selected},{role:'assistant',content:result.answer,sources:result.sources,language:selected}].slice(-40);u.tutorDraft='';save();question.value='';paint();status.textContent='Готово. Можно задать уточняющий вопрос.'}catch(e){status.textContent=e.name==='TimeoutError'?'Ответ занял слишком много времени. Вопрос сохранён. Попробуй ещё раз.':e.message}finally{busy=false;send.disabled=false}}
 }
};
